INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-bar', 0, 'lab', 'Панель на flexbox', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Сделайте из .bar горизонтальную панель: элементы в ряд, по краям, по центру по вертикали, с промежутком не меньше 16 пикселей.', '', 'display: flex включает флексбокс; justify-content раскладывает вдоль главной оси, align-items — поперёк, gap задаёт промежуток.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-column', 1, 'lab', 'Колонка вместо ряда', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Сделайте из .stack флекс-контейнер, в котором элементы идут столбиком: главная ось вертикальная. Между элементами — промежуток не меньше 8 пикселей.', '', 'Направление главной оси задаёт flex-direction. Значение column ведёт ось сверху вниз.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-justify', 2, 'lab', 'Равные промежутки', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Разложите кнопки .toolbar по ряду так, чтобы свободное место доставалось и промежуткам между кнопками, и краям (подойдёт space-around или space-evenly).', '', 'justify-content: space-around даёт каждому элементу равные поля с обеих сторон, space-evenly делает одинаковыми все промежутки, включая крайние.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-baseline', 3, 'lab', 'Одна базовая линия', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Крупная цифра .num и мелкая подпись .cur стоят в одной строке. Сделайте .price флекс-контейнером и выровняйте элементы по базовой линии текста, чтобы подпись не «плавала».', '', 'align-items: baseline выравнивает элементы по базовой линии их первой строки текста.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-gaps', 4, 'lab', 'Разные промежутки', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Фишки .chip переносятся в контейнере .board на несколько строк. Сделайте промежуток 8 пикселей между строками и 24 пикселя между столбцами одним свойством gap.', '', 'gap принимает два значения: сначала между строками (row-gap), потом между столбцами (column-gap).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-wrap', 5, 'lab', 'Перенос строк', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Теги .tag не помещаются в одну строку. Сделайте из .tags флекс-контейнер, который переносит элементы на новую строку, с промежутком не меньше 8 пикселей и между строками, и между столбцами.', '', 'flex-wrap: wrap разрешает перенос. Промежуток по обеим осям — gap (или row-gap и column-gap).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-grow', 6, 'lab', 'Пропорции flex', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Ряд .row — флекс-контейнер; левая колонка .a занимает 1 часть, правая .b — 2 части свободного места (сокращение flex).', '', 'flex: 1 и flex: 2 задают flex-grow 1 и 2 (и flex-basis 0%).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-sidebar', 7, 'lab', 'Боковая колонка не сжимается', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Сделайте .layout флекс-контейнером. Боковая колонка .side — ровно 240 пикселей по базе и никогда не сжимается; основная часть .main забирает всё оставшееся место.', '', 'flex: 0 0 240px — не расти, не сжиматься, база 240px. Для основной части достаточно flex: 1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-center', 8, 'lab', 'Центр по обеим осям', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Блок .box лежит внутри .hero, у которого уже задана минимальная высота. Поставьте .box точно по центру .hero: и вдоль, и поперёк.', '', 'Нужны три свойства у контейнера: display: flex, justify-content: center (вдоль) и align-items: center (поперёк).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-auto', 9, 'lab', 'margin-left: auto', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Сделайте из .top флекс-контейнер: все ссылки идут слева, а «Войти» (.login) уезжает к правому краю. Значение justify-content у .top менять нельзя — используйте автоматическое поле.', '', 'Левое поле auto забирает всё свободное место и сдвигает элемент вправо.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-self', 10, 'lab', 'align-self у одного элемента', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Карточки стоят у верхнего края ряда .row. Опустите к нижнему краю только карточку .warn, не меняя ни выравнивание ряда, ни остальные карточки.', '', 'align-self у отдельного элемента переопределяет align-items контейнера. Правило нужно только для .warn.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-order', 11, 'lab', 'Закреплённая запись вперёд', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. В разметке закреплённая запись .pin стоит последней, а на экране должна быть первой. Не трогая разметку и направление столбца, переставьте только её.', '', 'order по умолчанию равен нулю; отрицательное число отправляет элемент вперёд всех остальных.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-reverse', 12, 'lab', 'Шаги справа налево', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Шаги .step идут в разметке как 1, 2, 3, а показать их нужно справа налево: 3, 2, 1. Сделайте .steps флекс-контейнером с обратным рядом.', '', 'flex-direction: row-reverse разворачивает главную ось справа налево; переставлять элементы через order не нужно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-cards', 13, 'lab', 'Карточки равной высоты', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Ряд .cards — флекс-контейнер, но карточки разной высоты прижаты к верху. Сделайте так, чтобы каждая карточка тянулась до высоты самой высокой в ряду и все карточки делили ряд поровну.', '', 'align-items: stretch — значение по умолчанию, его перебивает flex-start. Чтобы делить ряд поровну, у карточки нужен flex: 1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-sticky', 14, 'lab', '«Липкий» подвал', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Страница .page — колонка минимум на всю высоту окна (100vh). Основная часть main забирает всё свободное место, чтобы подвал оставался внизу даже при малом содержимом.', '', 'У контейнера: display: flex, flex-direction: column и min-height: 100vh. У main: flex: 1 (или flex-grow: 1).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-ellipsis', 15, 'lab', 'Обрезка текста: min-width: 0', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Название файла .title не помещается и распирает ряд .row. Разрешите ему сжиматься (min-width: 0) и обрежьте текст в одну строку с многоточием: скрытое переполнение, text-overflow, white-space.', '', 'Нужны четыре свойства у .title: min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-media', 16, 'lab', 'Адаптивный flex', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Сделайте .cols флекс-контейнером с промежутком не меньше 8 пикселей: на широком окне колонки стоят рядом, а на узком (до 600 пикселей) встают друг под другом.', '', 'На узком окне перебейте направление: @media (max-width: 600px) { .cols { flex-direction: column; } }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-holy', 17, 'lab', 'Священный грааль', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Соберите макет страницы: .page — колонка на всю высоту окна; .mid занимает всё свободное место по высоте и сам является рядом; в нём боковые колонки nav и aside держат ширину 160 пикселей и не сжимаются, а main растягивается.', '', 'Два вложенных флекс-контейнера: .page (колонка, min-height: 100vh) и .mid (ряд). У .mid и main — flex: 1; у боковых колонок — flex: 0 0 160px.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 19, 'w19-sel-items', 18, 'lab', 'Флекс-элементы меню', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны только прямые дети списка .menu — именно они были бы флекс-элементами; вложенный список и ссылки внутри пунктов трогать нельзя.', '', 'Знак «>» между селекторами означает «непосредственный ребёнок». Пробел выбрал бы потомков на любой глубине.', '{}');
